import importlib, os, sys
import pytest


class _Collect:
    def __init__(self):
        self.outcomes = {}

    def pytest_runtest_logreport(self, report):
        name = report.nodeid.split("::", 1)[-1]
        if report.when == "call" or report.outcome != "passed":
            self.outcomes[name] = report.outcome


def run_pytest(*args, patch=None):
    """Запустить pytest на решении. Возвращает (код выхода, {имя теста: passed/failed/skipped})."""
    if os.getcwd() not in sys.path:
        sys.path.insert(0, os.getcwd())
    sys.modules.pop("solution", None)
    if patch:
        # Модуль импортируется заранее только ради подмены: иначе пусть его импортирует сам
        # pytest — с уже подключёнными плагинами (декораторы Allure работают только так).
        module = importlib.import_module("solution")
        for name, value in patch.items():
            setattr(module, name, value)
    collector = _Collect()
    code = pytest.main(["-q", "-p", "no:cacheprovider", "solution.py", *args], plugins=[collector])
    return int(code), collector.outcomes

import glob, json, shutil


def run_allure(*args, patch=None):
    # Прогон с --alluredir. Возвращает (код, {имя в отчёте: результат}) — результат как в JSON Allure.
    shutil.rmtree("ar", ignore_errors=True)
    code, _ = run_pytest("--alluredir=ar", *args, patch=patch)
    results = {}
    for path in glob.glob("ar/*-result.json"):
        with open(path, encoding="utf-8") as f:
            r = json.load(f)
        results[r["name"]] = r
    return code, results


def label(result, name):
    return [l["value"] for l in result.get("labels", []) if l["name"] == name]


def step_names(result):
    names = []
    def walk(steps, depth):
        for s in steps:
            names.append("  " * depth + s["name"])
            walk(s.get("steps", []), depth + 1)
    walk(result.get("steps", []), 0)
    return names


def attachments(result):
    found = list(result.get("attachments", []))
    def walk(steps):
        for s in steps:
            found.extend(s.get("attachments", []))
            walk(s.get("steps", []))
    walk(result.get("steps", []))
    return found

def test_allure_result():
    code, res = run_allure()
    assert "test_status" in res, f"В отчёте нет test_status: {list(res)}"
    assert res["test_status"]["status"] == "passed", res["test_status"]["status"]

